using Microsoft.Extensions.Options;
using NSubstitute;
using QuestPDF.Infrastructure;
using SMSMarica.Core.Laudos;
using SMSMarica.Core.Laudos.Configuracao;
using SMSMarica.Core.Laudos.Configuracao.Dtos;
using SMSMarica.Core.Laudos.Pdf;
using SMSMarica.Core.Midias;
using SMSMarica.Core.Pacientes;
using SMSMarica.Core.Midias.Dtos;
using SMSMarica.Data.Entities;
using SMSMarica.Data.Entities.Enums;

namespace SMSMarica.Tests.Laudos;

public class LaudoPdfCabecalhoTabelaTests
{
    [Fact]
    public async Task Gera_pdf_com_cabecalho_tabela_lado_a_lado()
    {
        QuestPDF.Settings.License = LicenseType.Community;
        var brasaoId = Guid.Parse("00000000-0000-0000-0000-00000000a005");
        var susId = Guid.Parse("00000000-0000-0000-0000-00000000a006");
        var brasao = Convert.FromBase64String(BrasaoB64);
        var sus = Convert.FromBase64String(SusB64);

        var html = @"<table><tr><td><img src=""https://api.smsmarica.online/midias/00000000-0000-0000-0000-00000000a005"" width=""44""></td><td><p style=""text-align: center""><strong>ESTADO DO RIO DE JANEIRO</strong></p><p style=""text-align: center""><strong>PREFEITURA MUNICIPAL DE MARICÁ</strong></p><p style=""text-align: center""><strong>SECRETARIA MUNICIPAL DE SAÚDE</strong></p><p style=""text-align: center"">SUBSECRETARIA DE ATENÇÃO BÁSICA</p><p style=""text-align: center"">CDT - CENTRO DE DIAGNÓSTICO E TRATAMENTO</p></td><td><img src=""https://api.smsmarica.online/midias/00000000-0000-0000-0000-00000000a006"" width=""90""></td></tr></table>";

        var laudosSvc = Substitute.For<ILaudosService>();
        var laudo = new Laudo
        {
            Id = Guid.NewGuid(),
            Titulo = "MAMOGRAFIA DIGITAL BILATERAL",
            ConteudoHtml = "<h3>INDICAÇÃO</h3><p>Exame de rastreamento.</p><h3>AVALIAÇÃO</h3><p>Categoria 2 (BI-RADS)</p>",
            Status = StatusLaudo.Finalizado,
            MedicoNomeSnapshot = "Dra. Claudia Freixo Seixas",
            MedicoCrmSnapshot = "52702650",
            MedicoUfCrmSnapshot = "RJ",
            StudyInstanceUID = "2.25.123",
            CriadoEm = DateTime.UtcNow,
            FinalizadoEm = DateTime.UtcNow,
        };
        laudosSvc.CarregarParaPdfAsync(Arg.Any<Guid>(), Arg.Any<CancellationToken>()).Returns(laudo);

        var cfg = Substitute.For<ILaudoConfiguracaoService>();
        cfg.ObterAsync(Arg.Any<CancellationToken>())
            .Returns(new LaudoConfiguracaoDto(html, "{}", string.Empty, "{}", DateTime.UtcNow));

        var midias = Substitute.For<IMidiasService>();
        midias.ObterConteudoAsync(brasaoId, Arg.Any<CancellationToken>())
            .Returns(new MidiaConteudo(brasao, "image/png", "brasao.png"));
        midias.ObterConteudoAsync(susId, Arg.Any<CancellationToken>())
            .Returns(new MidiaConteudo(sus, "image/png", "sus.png"));

        var pacientes = Substitute.For<IPacientesService>();
        var renderer = new LaudoPdfRenderer(laudosSvc, cfg, midias, pacientes, Options.Create(new LaudosPdfOptions()));
        var pdf = await renderer.GerarAsync(laudo.Id);

        pdf.Should().NotBeNullOrEmpty();
        // %PDF magic — confirma que renderizou um PDF válido (cabeçalho em tabela
        // logo|texto|logo não quebra a geração).
        System.Text.Encoding.ASCII.GetString(pdf, 0, 4).Should().Be("%PDF");
    }

    private const string BrasaoB64 = "";
    private const string SusB64 = "";
}
